CREATE TEMPORARY VIEW traffic_data_${grass_region_without_quote} AS
SELECT
     user_id
    ,shop_id
    ,item_id
    ,model_id
    ,is_ads
    ,mapping_general
    ,is_cheapest_item as cheapest_item
    ,is_cheapest_cspu_all_item as cheapest_cspu_all_item
    ,is_cheapest_model as cheapest_model
    ,is_cheapest_cspu_all_model as cheapest_cspu_all_model
    ,sum(imp_cnt) as imp_cnt
    ,sum(order_cnt) as order_cnt
    ,sum(gmv) as gmv
    ,sum(gmv_local) as gmv_local
from(
   select
   *
   from srdi_mart.dws_sr_data_warehouse_tc_pb_basic_tag_aggr_1d
    WHERE grass_region IN (${grass_region}) AND local_date = ${local_date}
    and  mapping_general in ('Search', 'Daily Discover', 'You May Also Like', 'Post Purchase')
)
group by
     user_id
    ,shop_id
    ,item_id
    ,model_id
    ,is_ads
    ,mapping_general
    ,is_cheapest_item
    ,is_cheapest_cspu_all_item
    ,is_cheapest_model
    ,is_cheapest_cspu_all_model
;

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_tc_pb_cheapest_sr_user_level_aggr_1d
partition (grass_region = ${grass_region},local_date = ${local_date})
select
     if (grouping(is_ads) = 1, '__ALL__', is_ads) as is_ads
    ,mapping_general
    ,user_id

    ,sum(if (cheapest_model = 1, order_cnt, 0)) as cheapest_model_order_cnt
    ,count(distinct if (cheapest_model=1 and order_cnt > 0, user_id, null)) as cheapest_model_order_uv
    ,sum(if (cheapest_model = 1, gmv, 0)) as cheapest_model_gmv
    ,sum(if (cheapest_model = 1, gmv_local, 0)) as cheapest_model_gmv_local
    ,sum(if (cheapest_item = 1, imp_cnt, 0)) as cheapest_item_imp_pv
    ,count(distinct if (cheapest_item=1 and imp_cnt > 0, user_id, null)) as cheapest_item_imp_uv
    ,sum(if (cheapest_item = 1, order_cnt, 0)) as cheapest_item_order_cnt
    ,count(distinct if (cheapest_item=1 and order_cnt > 0, user_id, null)) as cheapest_item_order_uv
    ,sum(if (cheapest_item = 1, gmv, 0)) as cheapest_item_gmv
    ,sum(if (cheapest_item = 1, gmv_local, 0)) as cheapest_item_gmv_local

    ,sum(if (cheapest_cspu_all_item = 1, imp_cnt, 0)) as cspu_item_imp_pv
    ,count(distinct if (cheapest_cspu_all_item=1 and imp_cnt > 0, user_id, null)) as cspu_item_imp_uv
    ,sum(if (cheapest_cspu_all_model = 1, order_cnt, 0)) as cspu_model_order_cnt
    ,count(distinct if (cheapest_cspu_all_model=1 and order_cnt > 0, user_id, null)) as cspu_model_order_uv
    ,sum(if (cheapest_cspu_all_model = 1, gmv, 0)) as cspu_model_gmv
    ,sum(if (cheapest_cspu_all_model = 1, gmv_local, 0)) as cspu_model_gmv_local

    ,sum(imp_cnt) as scene_imp_pv
    ,count(distinct if (imp_cnt > 0, user_id, null)) as scene_imp_uv
    ,sum(order_cnt) as scene_order_cnt
    ,count(distinct if (order_cnt > 0, user_id, null)) as scene_order_uv
    ,sum(gmv) as scene_gmv
    ,sum(gmv_local) as scene_gmv_local

from traffic_data_${grass_region_without_quote}
group by
     mapping_general
    ,is_ads
    ,user_id
grouping sets (
    (user_id, mapping_general, is_ads),
    (user_id, mapping_general)
)
